#!/usr/bin/env bash
set -euo pipefail

# The upload contains only the verified static/PHP build, never private tokens.
# Published client data is generated by PHP on the server and must survive deploys.
source_dir="${1:-hosting-dist}"
for variable in NAMINA_SSH_HOST NAMINA_SSH_PORT NAMINA_SSH_USER NAMINA_SSH_PRIVATE_KEY NAMINA_SSH_KNOWN_HOSTS NAMINA_PUBLIC_HTML; do
  if [[ -z "${!variable:-}" ]]; then
    printf 'Missing GitHub Actions secret: %s\n' "$variable" >&2
    exit 1
  fi
done

if [[ ! -d "$source_dir" || ! -f "$source_dir/index.html" || ! -f "$source_dir/api/generator.php" ]]; then
  printf 'Website build is incomplete; deployment refused.\n' >&2
  exit 1
fi

if [[ ! "$NAMINA_SSH_PORT" =~ ^[0-9]{1,5}$ ]] || (( 10#$NAMINA_SSH_PORT < 1 || 10#$NAMINA_SSH_PORT > 65535 )); then
  printf 'Invalid NAMINA_SSH_PORT.\n' >&2
  exit 1
fi
if [[ ! "$NAMINA_SSH_HOST" =~ ^[a-zA-Z0-9.-]+$ || ! "$NAMINA_SSH_USER" =~ ^[a-zA-Z0-9_-]+$ ]]; then
  printf 'Invalid SSH host or user.\n' >&2
  exit 1
fi
if [[ ! "$NAMINA_PUBLIC_HTML" =~ ^/home/[a-zA-Z0-9_-]+/public_html/?$ ]]; then
  printf 'Target must be the dedicated cPanel /home/USER/public_html directory.\n' >&2
  exit 1
fi

target_dir="${NAMINA_PUBLIC_HTML%/}"
ssh_dir="$(mktemp -d)"
trap 'rm -f "$ssh_dir/deploy_key" "$ssh_dir/known_hosts"; rmdir "$ssh_dir"' EXIT
chmod 700 "$ssh_dir"
printf '%s\n' "$NAMINA_SSH_PRIVATE_KEY" > "$ssh_dir/deploy_key"
printf '%s\n' "$NAMINA_SSH_KNOWN_HOSTS" > "$ssh_dir/known_hosts"
chmod 600 "$ssh_dir/deploy_key" "$ssh_dir/known_hosts"

ssh_options=(
  -i "$ssh_dir/deploy_key"
  -p "$NAMINA_SSH_PORT"
  -o BatchMode=yes
  -o IdentitiesOnly=yes
  -o StrictHostKeyChecking=yes
  -o "UserKnownHostsFile=$ssh_dir/known_hosts"
)

# Never create an unexpected webroot. Verify it already exists on this host.
ssh "${ssh_options[@]}" "$NAMINA_SSH_USER@$NAMINA_SSH_HOST" \
  "test -d '$target_dir' && command -v rsync >/dev/null"

printf 'Deploying NAMINA website to verified cPanel public_html.\n'
rsync -rltz --delay-updates --itemize-changes \
  --include='/clients/' \
  --include='/clients/vini.json' \
  --exclude='/clients/***' \
  -e "ssh -i $ssh_dir/deploy_key -p $NAMINA_SSH_PORT -o BatchMode=yes -o IdentitiesOnly=yes -o StrictHostKeyChecking=yes -o UserKnownHostsFile=$ssh_dir/known_hosts" \
  "$source_dir/" "$NAMINA_SSH_USER@$NAMINA_SSH_HOST:$target_dir/"

# Intentionally no --delete: keep published /{slug}/ pages and old hashed assets.
printf 'Website deployed. Existing generated client records/pages were preserved.\n'
